// Simpan data terakhir
var data = msg.payload;
data.received = new Date().toISOString();
flow.set('lastSensor', data);

// Simpan history (max 50 data)
var history = flow.get('history') || [];
history.push(data);
if (history.length > 50) history.shift();
flow.set('history', history);

// Cek batas suhu (default 30)
var t = flow.get('threshold');
if (t === undefined || t === null) t = 30;
var over = Number(data.suhu) > t;
var was = flow.get('overThreshold') || false;
flow.set('overThreshold', over);

// Kirim notifikasi hanya saat suhu BARU melewati batas (tidak spam)
if (over && !was) {
    var alert = {
        time: data.received,
        suhu: data.suhu,
        threshold: t,
        message: 'Suhu ' + data.suhu + '°C melewati batas ' + t + '°C'
    };
    var alerts = flow.get('alerts') || [];
    alerts.push(alert);
    if (alerts.length > 20) alerts.shift();
    flow.set('alerts', alerts);
    return [msg, {topic: 'iot/alert', payload: alert}];
}
return [msg, null];

var key = env.get('API_KEY') || 'iot-secret-123';
if (msg.req.headers['x-api-key'] === key) {
    return [msg, null];
}
msg.statusCode = 401;
msg.payload = {status: 'error', message: 'API key salah atau tidak ada (header X-API-Key)'};
msg.headers = {'Access-Control-Allow-Origin': '*'};
return [null, msg];

var data = flow.get('lastSensor') || {suhu: null, kelembaban: null, timestamp: null};
var t = flow.get('threshold');
if (t === undefined || t === null) t = 30;
